Expression:
IF (
    HORO_CONSOL[Equipo] IN { 100636, 620903, 618269 },

    // 🔒 CANDADO: Si alguna de las dos percusiones es nula o cero, la dejamos vacía
    IF (
        ISBLANK(HORO_CONSOL[Max_Percusion1]) || HORO_CONSOL[Max_Percusion1] = 0 ||
        ISBLANK(HORO_CONSOL[Max_Percusion2]) || HORO_CONSOL[Max_Percusion2] = 0,
        BLANK(), // Casilla en blanco para no afectar promedios
        HORO_CONSOL[Max_Percusion1] + HORO_CONSOL[Max_Percusion2]
    ),

    // Si es cualquier otro equipo, trae el horómetro eléctrico normal
    HORO_CONSOL[Max_Electrico]
)
